'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),{spawnSync}=require('node:child_process');const root=process.env.PUBLIC_TEST_TMP_ROOT||process.env.RUNNER_TEMP,python=process.env.PUBLIC_TEST_PYTHON;assert(root&&python);const bootstrap=fs.readFileSync(path.join(__dirname,'bootstrap.py'),'utf8');const hash=raw=>crypto.createHash('sha256').update(raw).digest('hex');
function run(mode){const dir=fs.mkdtempSync(path.join(root,'pure-bootstrap-')),bin=path.join(dir,'bin'),site=path.join(dir,'lib/python3.13/site-packages'),pkg=path.join(site,'just_akash');fs.mkdirSync(bin,{recursive:true});fs.mkdirSync(pkg,{recursive:true});const exe=path.join(bin,'python');fs.symlinkSync(python,exe);const marker=path.join(dir,'sdk-executed'),helper=path.join(dir,'helper-executed'),pth=path.join(dir,'pth-executed');fs.writeFileSync(path.join(site,'bad.pth'),`import pathlib;pathlib.Path(${JSON.stringify(pth)}).write_text('BAD')\n`);
 let code=`from pathlib import Path\nimport os\ndef main():\n    Path(os.environ['PUBLIC_RESULT']).write_text('CAPTURED')\n`;if(mode==='forbidden')code=`from . import forbidden\n`+code;if(mode==='unlocked')code=`from pathlib import Path\nimport os\ndef main():\n    enable_runtime()\n    from . import forbidden\n    Path(os.environ['PUBLIC_RESULT']).write_text('CAPTURED')\n`;
 const file=path.join(pkg,'keydb_qualification_fenced_controller.py');fs.writeFileSync(file,code);fs.writeFileSync(path.join(pkg,'forbidden.py'),`from pathlib import Path\nPath(${JSON.stringify(helper)}).write_text('HELPER')\n`);const pins={'just_akash.keydb_qualification_fenced_controller':hash(code)};if(mode==='changed')fs.appendFileSync(file,'\n# unadmitted body change\n');
 const value=spawnSync(exe,['-I','-S','-c',bootstrap,JSON.stringify(pins)],{env:{PATH:process.env.PATH,PUBLIC_RESULT:marker,PYTHONDONTWRITEBYTECODE:'1'},encoding:'utf8',timeout:10000});fs.writeFileSync(path.join(dir,'public-observation.json'),JSON.stringify({status:value.status,signal:value.signal,error:value.error?value.error.name:null}));return {value,marker,helper,pth};}
test('actual fixed -I -S bootstrap captures source before execution and never evaluates site pth',()=>{const x=run('positive');assert.equal(x.value.status,0);assert.equal(fs.readFileSync(x.marker,'utf8'),'CAPTURED');assert(!fs.existsSync(x.pth));assert(!fs.existsSync(x.helper));});
test('actual changed source is refused before any SDK code executes',()=>{const x=run('changed');assert.notEqual(x.value.status,0);assert(!fs.existsSync(x.marker)&&!fs.existsSync(x.helper)&&!fs.existsSync(x.pth));});
test('unlisted SDK effect/helper import is closed before MAY_CREATE',()=>{const x=run('forbidden');assert.notEqual(x.value.status,0);assert(!fs.existsSync(x.marker)&&!fs.existsSync(x.helper)&&!fs.existsSync(x.pth));});
test('explicit runtime handover is separate from pure captured phase',()=>{const x=run('unlocked');assert.equal(x.value.status,0);assert(fs.existsSync(x.marker)&&fs.existsSync(x.helper));assert(!fs.existsSync(x.pth));});
